  ? scripts.filter(s => scriptIds.includes(s.id))
  : scripts;

const items = targetScripts.map(s => ({ json: {
  record_id: s.id,
  pm_status: 'Rejected',
  pm_notes: notes || 'Revision needed',
  overall_status: 'PM Review'
}}));

return items;

const err = $input.first().json;
let project_id = 'N/A';
try { project_id = $('Extract Delivery Payload').first().json.project_id; } catch(e) {}
return [{ json: { project_id, error_message: err.error?.message || err.message || 'Unknown', error_node: err.error?.node?.name || 'Unknown', created_at: new Date().toISOString() } }];

const data = $('Prepare Notification').first().json;
return [{ json: {
  status: 'success',
  action: 'delivered',
  project_id: data.project_id,
  brand: data.brand_name,
  client_code: data.client_code,
  scripts_delivered: data.total_scripts,
  message: 'Scripts delivered to Google Docs, ClickUp, and Airtable. Client notified.'
} }];

// ============================================================
// Send to Client: Update script statuses and prepare doc sharing
// ============================================================
const data = $input.first().json;
const project = data.project;
const scripts = data.scripts;
const scriptIds = data.script_ids || [];
const brandName = project.brand_name || 'Brand';
const clientName = project.client_name || 'Client';
const clientEmail = project.client_email || '';

const targetScripts = scriptIds.length > 0
  ? scripts.filter(s => scriptIds.includes(s.id))
  : scripts;

// Build update items for each script
const items = targetScripts.map(s => ({ json: {
  record_id: s.id,
  overall_status: 'Client Review',
  client_status: 'Pending'
}}));

return items.length ? items : [{ json: { _skip: true } }];

