    props: s.props,
    references: s.references,
    creative_table: s.creative_table,
    creator_notes: s.creator_notes,
    visual_direction: s.visual_direction,
    on_screen_text: s.on_screen_text,
    thumbnail_frame: s.thumbnail_frame,
    brand_name: data.brand_name,
    product_feature: data.product_feature,
    client_code: data.client_code
  }
}));

return items.length ? items : [{ json: { _skip: true } }];

// ============================================================
// Build Doc Requests — Step A
// Build Google Docs API batchUpdate requests for production brief
// First clears existing content, then inserts new production brief
// ============================================================

// Get script data from Doc Found? node (passed through Read Doc Before Write)
const docData = $('Doc Found?').first().json;
const docStructure = $input.first().json;

// Validate document body was read successfully
if (!docStructure.body || !docStructure.body.content || docStructure.body.content.length === 0) {
  throw new Error('Failed to read document - cannot proceed with stale data');
}

const docId = docData.doc_id;
const brandName = docData.brand_name || 'Brand';
const num = docData.script_number || 1;
const conceptName = docData.concept_name || 'Concept';
const conceptStory = docData.concept_story || '';
const productFeature = docData.product_feature || '';
const format = docData.format || 'UGC';
const duration = docData.estimated_duration || '30 sec';
const costumes = Array.isArray(docData.costumes) ? docData.costumes : [];
const props = Array.isArray(docData.props) ? docData.props : [];
const references = Array.isArray(docData.references) ? docData.references : [];
const creativeTable = Array.isArray(docData.creative_table) ? docData.creative_table : [];
const hook1 = docData.hook_1 || docData.hook || '';
const hook2 = docData.hook_2 || '';
const hook3 = docData.hook_3 || '';
const creatorNotes = docData.creator_notes || '';
const clientCode = docData.client_code || '';

// Build header text
const lines = [];
lines.push(`${brandName} | UGC Script #${num} — ${conceptName}`);
lines.push('');
lines.push(`Product: ${productFeature || 'N/A'}`);
lines.push(`Format: ${format} | Duration: ${duration}`);
lines.push('');
lines.push(`Concept: ${conceptStory || conceptName}`);
lines.push('');

// Costumes section
lines.push('COSTUMES');
if (costumes.length > 0) {
  costumes.forEach(c => {
    const link = c.reference_link ? ` (${c.reference_link})` : '';
    lines.push(`  • ${c.item || c}${link}`);
  });
} else {
  lines.push('  • N/A');
}
lines.push('');

// Props section
lines.push('PROPS');
if (props.length > 0) {
  props.forEach(p => lines.push(`  • ${p}`));
} else {
  lines.push('  • N/A');
}
lines.push('');

// References section
lines.push('REFERENCES');
if (references.length > 0) {
  references.forEach(r => {
    const link = r.link ? ` — ${r.link}` : '';
    lines.push(`  • ${r.description || r}${link}`);
  });
} else {
  lines.push('  • N/A');
}
lines.push('');

// Creative Format header
lines.push('CREATIVE FORMAT');
lines.push('');

const headerText = lines.join('\n');

// Table dimensions
const tableRows = creativeTable.length + 1; // +1 for header row
const tableCols = 3;

// After-table text
const afterLines = [];
afterLines.push('');
afterLines.push('HOOK VARIATIONS');
afterLines.push(`  1. ${hook1}`);
afterLines.push(`  2. ${hook2}`);
afterLines.push(`  3. ${hook3}`);
afterLines.push('');
if (creatorNotes) {
  afterLines.push(`CREATOR NOTES: ${creatorNotes}`);
  afterLines.push('');
}
afterLines.push(`Generated by Smashed Agency UGC Script Agent`);
afterLines.push(`Client: ${clientCode} | ${new Date().toISOString().split('T')[0]}`);
const afterText = afterLines.join('\n');

// Build requests
const requests = [];

// Step 1: Delete all existing content if document has content beyond the initial newline
const bodyContent = docStructure.body?.content || [];
const lastElement = bodyContent[bodyContent.length - 1];
const docEndIndex = lastElement?.endIndex || 2;
if (docEndIndex > 2) {
  requests.push({
    deleteContentRange: {
      range: { startIndex: 1, endIndex: docEndIndex - 1 }
    }
  });
}

// Step 2: Insert header text at index 1
requests.push({
  insertText: {
    location: { index: 1 },
    text: headerText
  }
});

// Step 3: Insert table after header text
const tableIndex = headerText.length + 1;
requests.push({
  insertTable: {
    location: { index: tableIndex },
    rows: tableRows,
    columns: tableCols
  }
});

return [{ json: {
  doc_id: docId,
  header_text: headerText,
  after_text: afterText,
  table_rows: tableRows,
  table_cols: tableCols,
  creative_table: creativeTable,
  header_length: headerText.length,
  requests_json: JSON.stringify({ requests })
} }];

// ============================================================
// Build Cell Requests — Step D
// Parse document structure, find table cells, build insertText
// requests for each cell with voiceover/visuals/references content
// ============================================================

const doc = $input.first().json;
const buildData = $('Build Doc Requests').first().json;
const docId = buildData.doc_id;
const creativeTable = buildData.creative_table || [];

// Find the table in the document body
const body = doc.body || {};
const content = body.content || [];
let table = null;
let tableEndIndex = 0;

for (const element of content) {
  if (element.table) {
    table = element;
    tableEndIndex = element.endIndex;
    break;
  }
}

if (!table) {
  // No table found, just append the after text at the end
  const endIdx = body.content[body.content.length - 1]?.endIndex || 1;
  return [{ json: {
    doc_id: docId,
    cell_requests_json: JSON.stringify({ requests: [{ insertText: { location: { index: endIdx - 1 }, text: afterText } }] })
  } }];
}

const requests = [];
const rows = table.table.tableRows || [];

// Process in REVERSE order (Google Docs API requires reverse index order for inserts)
const cellInserts = [];

// Header row
const headerLabels = ['Voiceover / Dialogue', 'Visuals / Camera', 'References'];
const headerRow = rows[0];
if (headerRow) {
  for (let c = 0; c < 3; c++) {
    const cell = headerRow.tableCells[c];
    if (cell) {
      const cellContent = cell.content || [];
      const startIdx = cellContent[0]?.paragraph?.elements?.[0]?.startIndex || cell.startIndex + 1;
      // Find the actual insertion point inside the cell paragraph
      const paraStart = cellContent[0]?.startIndex || startIdx;
      cellInserts.push({ index: paraStart, text: headerLabels[c] });
    }
  }
}

// Data rows
for (let r = 1; r < rows.length; r++) {
  const row = rows[r];
  const sceneData = creativeTable[r - 1] || {};
  const cellTexts = [
    sceneData.voiceover || '',
    sceneData.visuals || '',
    sceneData.references || ''
  ];

  for (let c = 0; c < 3; c++) {
    const cell = row.tableCells[c];
    if (cell) {
      const cellContent = cell.content || [];
      const paraStart = cellContent[0]?.startIndex || (cell.startIndex + 1);
      cellInserts.push({ index: paraStart, text: cellTexts[c] });
    }
  }
}

// Sort by index DESCENDING (must insert from end to start to preserve indices)
cellInserts.sort((a, b) => b.index - a.index);

// Build insert requests
for (const ci of cellInserts) {
  if (ci.text) {
    requests.push({
      insertText: {
        location: { index: ci.index },
        text: ci.text
      }
    });
  }
}


return [{ json: {
  doc_id: docId,
  cell_requests_json: JSON.stringify({ requests })
} }];

// Prepare for ClickUp lookup after doc loop completes
const data = $('Format Approved Scripts').first().json;
return [{ json: data }];

// Find the brand's folder and extract the pipeline list ID
const folders = ($input.first().json.folders || []);
const data = $('Format Approved Scripts').first().json;
const target = data.brand_name + ' - UGC';
const folder = folders.find(f => f.name === target) || folders.find(f => f.name.toLowerCase().includes(data.brand_name.toLowerCase()));
if (!folder) return [{ json: { list_id: null } }];
const list = (folder.lists || []).find(l => l.name.includes('Pipeline')) || (folder.lists || [])[0];
return [{ json: { list_id: list ? list.id : null, folder_id: folder.id } }];

// Match scripts to UGC_C{N} ClickUp tasks
const tasks = ($input.first().json.tasks || []).filter(t => /^UGC_C\d+/.test(t.name)).sort((a, b) => {
  const nA = parseInt((a.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  const nB = parseInt((b.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  return nA - nB;
});
const scripts = $('Format Approved Scripts').first().json.scripts;
const items = scripts.map((s, i) => {
  const task = tasks[i];
  if (!task) return null;
  return { json: {
    task_id: task.id,
    description: `CONCEPT: ${s.concept_name}\nFORMAT: ${s.format}\nDURATION: ${s.estimated_duration}\n\n== FULL SCRIPT ==\n${s.full_script}\n\n== HOOK ==\n${s.hook}\n\n---\nAI-generated by Smashed Agency UGC Script Agent Team\nDelivered to client`
  }};
}).filter(Boolean);
return items.length ? items : [{ json: { _skip: true } }];

// ============================================================
// Update script records in Airtable to 'Delivered'
// Also stores google_doc_id from Match Scripts to Docs
// ============================================================
const data = $('Format Approved Scripts').first().json;

// Get doc IDs from the Match node (same execution, already ran)
let docMap = {};
try {
  const matchItems = $('Match Scripts to Docs').all();
  matchItems.forEach(item => {
    if (item.json.doc_id) {
      docMap[item.json.script_number] = item.json.doc_id;
    }
  });
} catch(e) {}

const items = data.scripts.map(s => ({ json: {
  record_id: s.script_id,
  pm_status: 'Approved',
  overall_status: 'Delivered',
  google_doc_id: docMap[s.script_number] || ''
}}));
return items.length ? items : [{ json: { _skip: true } }];

const data = $('Format Approved Scripts').first().json;
const summary = data.scripts.map(s => `  ${s.script_number}. "${s.concept_name}" (${s.format}) — "${(s.hook || '').substring(0, 50)}..."`).join('\n');
return [{ json: {
  brand_name: data.brand_name,
  client_code: data.client_code,
  client_name: data.client_name,
  total_scripts: data.total_scripts,
  script_summary: summary,
  project_id: data.project_id
} }];

